+import { useEffect, useState } from "react";
+import { supabase } from "./client";
+
+export function App() {
+  const [pending, setPending] = useState<any[]>([]);
+  useEffect(() => {
+    supabase.from("proposed_actions").select("*").eq("status", "pending").then(({ data }) => setPending(data ?? []));
+  }, []);
+  return <ul>{pending.map((a) => <li key={a.id}>{a.kind}</li>)}</ul>;
+}
